mapper.select:
select
*
from t_login_log


        AND user_id = #{query.userId}


        AND user_type = #{query.userType}


        AND login_ip ILIKE CONCAT('%', #{query.ip}, '%')


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= #{query.startDate}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= #{query.endDate}


        AND user_name ILIKE CONCAT('%', #{query.userName}, '%')


order by create_time desc

select
*
from t_login_log
where
    user_id = #{userId}
    and user_type = #{userType}
    and login_result = #{loginLogResult}
order by login_log_id desc
limit 1
